<style>*{box-sizing:border-box}body{margin:0;font-family:Inter,Arial,sans-serif;background:#f3f6f8;color:#172033}.wrap{max-width:1500px;margin:28px auto;padding:0 18px}.top{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;margin-bottom:18px}.btn{display:inline-flex;align-items:center;justify-content:center;border:0;border-radius:9px;padding:9px 13px;background:#102a43;color:#fff;text-decoration:none;font-weight:750;cursor:pointer}.btn.danger{background:#b91c1c}.grid6{display:grid;grid-template-columns:repeat(6,1fr);gap:12px;margin-bottom:18px}.card{background:#fff;border:1px solid #dfe7ed;border-radius:14px;padding:18px;box-shadow:0 5px 18px rgba(15,23,42,.04);margin-bottom:18px}.value{font-size:26px;font-weight:850;color:#0f766e}.muted{color:#64748b;font-size:13px}.forms{display:grid;grid-template-columns:1fr 1fr;gap:16px}.formgrid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.field label{display:block;font-size:12px;font-weight:800;color:#52677a;margin-bottom:5px}.field input,.field select{width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:9px;background:#fff}.full{grid-column:1/-1}.tablewrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}th,td{padding:10px;border-bottom:1px solid #e5e7eb;text-align:left;vertical-align:top}th{color:#52677a;background:#f8fafc}.badge{display:inline-block;padding:4px 8px;border-radius:999px;background:#ecfdf5;color:#047857;font-weight:800;font-size:11px}.badge.off{background:#f1f5f9;color:#64748b}.badge.due{background:#fff7ed;color:#b45309}.inline{display:flex;gap:6px;align-items:center;flex-wrap:wrap}.inline input,.inline select{padding:7px;border:1px solid #cbd5e1;border-radius:7px}.success,.error{padding:12px 14px;border-radius:10px;margin-bottom:14px}.success{background:#ecfdf5;border:1px solid #86efac}.error{background:#fef2f2;border:1px solid #fca5a5}@media(max-width:1100px){.grid6{grid-template-columns:repeat(3,1fr)}}@media(max-width:900px){.forms{grid-template-columns:1fr}.formgrid{grid-template-columns:1fr}}@media(max-width:620px){.grid6{grid-template-columns:1fr 1fr}.top{flex-direction:column}}</style></head><body><div class="wrap">
<div class="top"><div><h1 style="margin:0">Locker Management & Billing</h1><div class="muted">Add any number of lockers, manage locker numbers, edit details, safely delete unused lockers, allocate lockers and collect monthly charges.</div></div><a class="btn" href="{{ route('admin.dashboard') }}">Dashboard</a></div>
