<div class="forms"><div class="card"><h2 style="margin-top:0">Add Locker / Increase Locker Count</h2><div class="muted" style="margin-bottom:12px">Create lockers one by one with any locker number. Total Locker count updates automatically.</div><form method="POST" action="{{ route('admin.lockers.store') }}">@csrf<div class="formgrid"><div class="field"><label>Branch</label><select name="branch_id" required><option value="">Select branch</option>@foreach($branches as $branch)<option value="{{ $branch->id }}">{{ $branch->name }}</option>@endforeach</select></div><div class="field"><label>Locker No.</label><input name="locker_no" placeholder="L-001" required></div><div class="field"><label>Location</label><input name="location" placeholder="Ground Floor / Hall entrance"></div><div class="field"><label>Monthly Charge (₹)</label><input type="number" step="0.01" min="0" name="monthly_charge" required></div><div class="field full"><label><input type="checkbox" name="status" value="1" checked style="width:auto"> Active</label></div></div><button class="btn" type="submit">Add Locker</button></form></div>
<div class="card"><h2 style="margin-top:0">Allocate Locker</h2><form method="POST" action="{{ route('admin.lockers.allocations.store') }}">@csrf<div class="formgrid"><div class="field"><label>Student</label><select name="student_id" required><option value="">Select student</option>@foreach($students as $student)<option value="{{ $student->id }}">{{ $student->student_code }} — {{ $student->name }}</option>@endforeach</select></div><div class="field"><label>Locker</label><select name="locker_id" required><option value="">Select locker</option>@foreach($lockers->where('status',true) as $locker)<option value="{{ $locker->id }}" @disabled($locker->active_allocations_count>0)>{{ $locker->locker_no }} — ₹{{ number_format((float)$locker->monthly_charge,2) }}/month{{ $locker->active_allocations_count>0?' — OCCUPIED':'' }}</option>@endforeach</select></div><div class="field"><label>From</label><input type="date" name="allocated_from" value="{{ now()->toDateString() }}" required></div><div class="field"><label>To</label><input type="date" name="allocated_to"></div><div class="field"><label>Status</label><select name="status"><option value="active">Active</option><option value="reserved">Reserved</option></select></div><div class="field"><label>Remarks</label><input name="remarks"></div></div><button class="btn" type="submit">Allocate Locker</button></form></div></div>
<div class="card"><h2>Locker Inventory — Add / Edit / Delete</h2><div class="muted" style="margin-bottom:12px">Locker No., location, monthly charge and status can be edited anytime. Delete is allowed only when the locker has never been allocated; lockers with history should be Disabled.</div><div class="tablewrap"><table><thead><tr><th>Branch</th><th>Locker No.</th><th>Location</th><th>Monthly Charge</th><th>Status</th><th>History</th><th>Actions</th></tr></thead><tbody>@forelse($lockers as $locker)<tr><td>{{ $locker->branch?->name }}</td><td><strong>{{ $locker->locker_no }}</strong></td><td>{{ $locker->location ?: '—' }}</td><td>₹{{ number_format((float)$locker->monthly_charge,2) }}</td><td><span class="badge {{ $locker->status?'':'off' }}">{{ $locker->status?'Active':'Disabled' }}</span></td><td>{{ $locker->allocations_count }} allocation(s)@if($locker->active_allocations_count>0)<div class="muted">Currently occupied</div>@endif</td><td><form class="inline" method="POST" action="{{ route('admin.lockers.update',$locker) }}">@csrf @method('PATCH')<input name="locker_no" value="{{ $locker->locker_no }}" size="8" required><input name="location" value="{{ $locker->location }}" placeholder="Location" size="12"><input type="number" step="0.01" min="0" name="monthly_charge" value="{{ $locker->monthly_charge }}" style="width:95px" required><select name="status"><option value="1" @selected($locker->status)>Active</option><option value="0" @selected(!$locker->status)>Disabled</option></select><button class="btn" type="submit">Save Edit</button></form>@if($locker->allocations_count===0)<form method="POST" action="{{ route('admin.lockers.destroy',$locker) }}" style="margin-top:7px" onsubmit="return confirm('Delete locker {{ $locker->locker_no }} permanently?')">@csrf @method('DELETE')<button class="btn danger" type="submit">Delete Locker</button></form>@else<div class="muted" style="margin-top:7px">Delete locked because allocation history exists. Disable instead.</div>@endif</td></tr>@empty<tr><td colspan="7">No lockers configured yet. Use Add Locker above.</td></tr>@endforelse</tbody></table></div></div>
<div class="card"><h2>Locker Allocations & Fee Collection</h2><div class="tablewrap"><table><thead><tr><th>Student</th><th>Locker</th><th>Period</th><th>Charge</th><th>Billing</th><th>Collect</th><th>Allocation</th></tr></thead><tbody>@forelse($allocations as $allocation)@php($isDue=$allocation->status==='active' && (!$allocation->paid_through || $allocation->paid_through->lt(today())))<tr><td><strong>{{ $allocation->student?->name }}</strong><div class="muted">{{ $allocation->student?->student_code }}</div></td><td>{{ $allocation->locker?->locker_no }}</td><td>{{ $allocation->allocated_from?->format('d M Y') }} — {{ $allocation->allocated_to?->format('d M Y') ?? 'Open ended' }}</td><td>₹{{ number_format((float)$allocation->monthly_charge,2) }}/month</td><td>@if($allocation->paid_through)<span class="badge {{ $isDue?'due':'' }}">Paid through {{ $allocation->paid_through->format('d M Y') }}</span>@else<span class="badge due">Not paid</span>@endif</td><td>@if(in_array($allocation->status,['active','reserved']))<form class="inline" method="POST" action="{{ route('admin.lockers.allocations.payments.store',$allocation) }}">@csrf<select name="billing_months"><option value="1">1 month</option><option value="3">3 months</option><option value="6">6 months</option><option value="12">12 months</option></select><input type="date" name="payment_date" value="{{ now()->toDateString() }}" required><select name="payment_mode"><option value="cash">Cash</option><option value="upi">UPI</option><option value="card">Card</option><option value="bank">Bank</option><option value="other">Other</option></select><button class="btn" type="submit">Collect</button></form>@endif</td><td><form class="inline" method="POST" action="{{ route('admin.lockers.allocations.update',$allocation) }}">@csrf @method('PATCH')<select name="status"><option value="reserved" @selected($allocation->status==='reserved')>Reserved</option><option value="active" @selected($allocation->status==='active')>Active</option><option value="completed" @selected($allocation->status==='completed')>Completed</option><option value="cancelled" @selected($allocation->status==='cancelled')>Cancelled</option></select><input type="date" name="allocated_to" value="{{ $allocation->allocated_to?->toDateString() }}"><button class="btn" type="submit">Update</button></form></td></tr>@empty<tr><td colspan="7">No locker allocations yet.</td></tr>@endforelse</tbody></table></div>{{ $allocations->links() }}</div>
<div class="card"><h2>Recent Locker Payments</h2><div class="tablewrap"><table><thead><tr><th>Receipt</th><th>Date</th><th>Student</th><th>Locker</th><th>Period</th><th>Amount</th></tr></thead><tbody>@forelse($payments as $payment)<tr><td>{{ $payment->receipt_no }}</td><td>{{ $payment->payment_date?->format('d M Y') }}</td><td>{{ $payment->student?->name }}</td><td>{{ $payment->allocation?->locker?->locker_no }}</td><td>{{ $payment->period_from?->format('d M Y') }} — {{ $payment->period_to?->format('d M Y') }}</td><td>₹{{ number_format((float)$payment->amount,2) }}</td></tr>@empty<tr><td colspan="6">No locker payments yet.</td></tr>@endforelse</tbody></table></div></div>
